+#[derive(Debug)]
+enum BufferStorage {
+    Inline(Option<Buffer>),
+    Heap(BinaryHeap<Buffer>),
+}
+
+impl Default for BufferStorage {
+    fn default() -> Self {
+        Self::Inline(None)
+    }
+}
+
+impl BufferStorage {
+    fn empty_for_compaction(&self) -> Self {
+        match self {
+            Self::Inline(_) => Self::default(),
+            Self::Heap(heap) => Self::Heap(BinaryHeap::with_capacity(heap.len())),
+        }
+    }
+
+    fn push(&mut self, buffer: Buffer) {
+        match self {
+            Self::Inline(slot) => match slot.take() {
+                None => *slot = Some(buffer),
+                Some(first) => *self = Self::Heap(BinaryHeap::from(vec![first, buffer])),
+            },
+            Self::Heap(heap) => heap.push(buffer),
+        }
+    }
+
+    fn peek(&self) -> Option<&Buffer> {
+        match self {
+            Self::Inline(slot) => slot.as_ref(),
+            Self::Heap(heap) => heap.peek(),
+        }
+    }
+
+    fn pop(&mut self) -> Option<Buffer> {
+        match self {
+            Self::Inline(slot) => slot.take(),
+            Self::Heap(heap) => heap.pop(),
+        }
+    }
+
+    fn len(&self) -> usize {
+        match self {
+            Self::Inline(slot) => usize::from(slot.is_some()),
+            Self::Heap(heap) => heap.len(),
+        }
+    }
+
+    fn is_empty(&self) -> bool {
+        self.len() == 0
+    }
+
+    fn clear(&mut self) {
+        // Keep a spilled heap's capacity across normal reads and stream reuse.
+        match self {
+            Self::Inline(slot) => *slot = None,
+            Self::Heap(heap) => heap.clear(),
+        }
+    }
+
+    fn iter(&self) -> impl Iterator<Item = &Buffer> {
+        let (inline, heap) = match self {
+            Self::Inline(slot) => (slot.as_ref(), None),
+            Self::Heap(heap) => (None, Some(heap)),
+        };
+        inline.into_iter().chain(heap.into_iter().flatten())
+    }
+
+    fn into_sorted_vec(self) -> Vec<Buffer> {
+        match self {
+            Self::Inline(slot) => slot.into_iter().collect(),
+            Self::Heap(heap) => heap.into_sorted_vec(),
+        }
+    }
+
+    #[cfg(test)]
+    fn capacity(&self) -> usize {
+        match self {
+            Self::Inline(_) => 0,
+            Self::Heap(heap) => heap.capacity(),
+        }
+    }
+}
