+    #[test]
+    fn inline_spill_partial_read_and_reuse_preserve_accounting() {
+        let mut x = Assembler::new();
+        x.insert(0, Bytes::from_static(b"abcd"), 8).unwrap();
+        assert_eq!(x.data.capacity(), 0);
+        assert_eq!((x.buffered, x.allocated), (4, 8));
+        assert_eq!(x.read(1, true), Some(Chunk::new(0, Bytes::from_static(b"a"))));
+        assert_eq!(x.data.capacity(), 0);
+        assert_eq!((x.buffered, x.allocated), (3, 8));
+        x.insert(4, Bytes::from_static(b"ef"), 6).unwrap();
+        let capacity = x.data.capacity();
+        assert!(capacity >= 2);
+        assert_eq!((x.buffered, x.allocated), (5, 14));
+        assert_eq!(x.read(1, true), Some(Chunk::new(1, Bytes::from_static(b"b"))));
+        assert_eq!((x.buffered, x.allocated), (4, 14));
+        assert_eq!(x.read(usize::MAX, true), Some(Chunk::new(2, Bytes::from_static(b"cd"))));
+        assert_eq!((x.buffered, x.allocated), (2, 6));
+        x.clear();
+        assert_eq!((x.buffered, x.allocated), (0, 0));
+        assert_eq!(x.bytes_read(), 4);
+        assert_eq!(x.data.capacity(), capacity);
+        x.reinit();
+        assert_eq!(x.bytes_read(), 0);
+        assert_eq!(x.data.capacity(), capacity);
+        x.insert(0, Bytes::from_static(b"abcdef"), 6).unwrap();
+        x.insert(2, Bytes::from_static(b"cdefgh"), 6).unwrap();
+        assert_eq!(x.data.capacity(), capacity);
+        // Advancing the first chunk past the second must restore heap ordering.
+        assert_eq!(x.read(3, true), Some(Chunk::new(0, Bytes::from_static(b"abc"))));
+        assert_eq!(x.read(2, true), Some(Chunk::new(3, Bytes::from_static(b"de"))));
+        assert_eq!(x.read(usize::MAX, true), Some(Chunk::new(5, Bytes::from_static(b"f"))));
+        assert_eq!(x.read(usize::MAX, true), Some(Chunk::new(6, Bytes::from_static(b"gh"))));
+        assert_eq!((x.buffered, x.allocated), (0, 0));
+        assert_eq!(x.bytes_read(), 8);
+        assert_eq!(x.data.capacity(), capacity);
+        x.discard_buffer();
+        assert_eq!(x.data.capacity(), 0);
+    }
+
+    #[test]
+    fn partial_inline_clear_and_retirement_release_only_staged_ownership() {
+        use std::sync::{Arc, atomic::{AtomicUsize, Ordering::SeqCst}};
+        struct Owned(Arc<AtomicUsize>);
+        impl AsRef<[u8]> for Owned {
+            fn as_ref(&self) -> &[u8] { b"abcd" }
+        }
+        impl Drop for Owned {
+            fn drop(&mut self) { self.0.fetch_add(1, SeqCst); }
+        }
+        for retirement in [false, true] {
+            let dropped = Arc::new(AtomicUsize::new(0));
+            let mut x = Assembler::new();
+            x.insert(0, Bytes::from_owner(Owned(dropped.clone())), 4).unwrap();
+            let first = x.read(1, true).unwrap();
+            assert_eq!(first.bytes, b"a"[..]);
+            assert_eq!((x.buffered, x.allocated), (3, 4));
+            if retirement { x.discard_buffer(); } else { x.clear(); }
+            assert_eq!((x.buffered, x.allocated), (0, 0));
+            assert_eq!(x.bytes_read(), 1);
+            assert_eq!(dropped.load(SeqCst), 0);
+            drop(first);
+            assert_eq!(dropped.load(SeqCst), 1);
+            x.insert(0, Bytes::from_static(b"abcd"), 4).unwrap();
+            assert_eq!(x.read(usize::MAX, true), Some(Chunk::new(1, Bytes::from_static(b"bcd"))));
+        }
+    }
